INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Einplatinencomputer nur mit Linux läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere OS wie Windows IoT möglich"}, {"text": "Ja", "correct": false, "because": "Mehrere Betriebssysteme kompatibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle nutze ich, um Sensoren anzuschließen?', 3, '[{"text": "GPIO-Pins", "correct": true, "because": "Ermöglicht direkte Hardwaresteuerung"}, {"text": "HDMI", "correct": false, "because": "Nur für Bildausgabe"}, {"text": "USB-C", "correct": false, "because": "Für Strom oder Peripherie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für ein IoT-Projekt essenziell?', 5, '[{"text": "WLAN-Modul", "correct": true, "because": "Ermöglicht Netzwerkverbindung"}, {"text": "Sensoren", "correct": true, "because": "Erfassen Umgebungsdaten"}, {"text": "High-End-GPU", "correct": false, "because": "Nicht primär nötig"}, {"text": "Touchscreen", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Einplatinencomputer kann als Mediencenter genutzt werden. b) Er ersetzt immer einen Desktop-PC.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, begrenzte Leistung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Boards für ein Retro-Gaming-Projekt?', 4, '[{"text": "Prozessorleistung", "correct": false, "because": "Wichtig für Emulation"}, {"text": "Speichergröße", "correct": false, "because": "Beeinflusst Performance"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Einplatinencomputer direkt eine Festplatte unterstützt?', 2, '[{"text": "Nein", "correct": true, "because": "Extern über USB oder Netzwerk"}, {"text": "Ja", "correct": false, "because": "Keine direkte SATA-Schnittstelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem ist für Anfänger am besten geeignet?', 3, '[{"text": "Raspberry Pi OS", "correct": true, "because": "Optimiert und benutzerfreundlich"}, {"text": "Arch Linux", "correct": false, "because": "Komplexere Konfiguration"}, {"text": "Kali Linux", "correct": false, "because": "Für Sicherheitstests spezialisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Einplatinencomputer keine Kühlung braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Intensive Aufgaben erfordern Kühlung"}, {"text": "Ja", "correct": false, "because": "Überhitzung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Python die einzige Programmiersprache für solche Boards?', 3, '[{"text": "Nein", "correct": true, "because": "Auch C++, Java und mehr möglich"}, {"text": "Ja", "correct": false, "because": "Mehrere Sprachen unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind nötig, um ein Board als Webserver einzurichten?', 4, '[{"text": "Apache oder Nginx installieren", "correct": true, "because": "Dient Webseiten aus"}, {"text": "Netzwerkverbindung konfigurieren", "correct": true, "because": "Ermöglicht Zugriff"}, {"text": "Grafische Oberfläche einrichten", "correct": false, "because": "Nicht zwingend"}, {"text": "Bluetooth aktivieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Projekt mit Echtzeit-Datenverarbeitung?', 4, '[{"text": "Prozessorleistung", "correct": true, "because": "Sichert schnelle Verarbeitung"}, {"text": "Großer Arbeitsspeicher", "correct": false, "because": "Hilfreich, aber sekundär"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) GPIO-Pins steuern externe Geräte. b) Sie ersetzen USB-Anschlüsse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, unterschiedliche Funktionen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein einfaches LED-Projekt?', 3, '[{"text": "GPIO-Pins", "correct": false, "because": "Steuern die LED"}, {"text": "Widerstände", "correct": false, "because": "Schützen die Schaltung"}, {"text": "High-End-Monitor", "correct": true, "because": "Nur für Ausgabe nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich ein Board für ein Smart-Home-Projekt vorbereite?', 4, '[{"text": "WLAN aktivieren und Sensoren anschließen", "correct": true, "because": "Ermöglicht Kommunikation und Steuerung"}, {"text": "3D-Drucker anschließen", "correct": false, "because": "Nicht erforderlich"}, {"text": "Spiele installieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Einplatinencomputer für Machine Learning ungeeignet ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Einfache Modelle machbar"}, {"text": "Ja", "correct": false, "because": "Mit Optimierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen nutze ich für ein Robotikprojekt?', 4, '[{"text": "GPIO für Sensoren", "correct": true, "because": "Steuert Hardware"}, {"text": "I2C für Kommunikation", "correct": true, "because": "Verbindet Module"}, {"text": "VGA", "correct": false, "because": "Veraltete Anzeige"}, {"text": "SATA", "correct": false, "because": "Nicht verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Einplatinencomputer mehrere Betriebssysteme gleichzeitig ausführen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur eines bootet"}, {"text": "Ja", "correct": false, "because": "Keine Dual-Boot-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Board für Bildungsprojekte?', 5, '[{"text": "Niedrige Kosten", "correct": true, "because": "Erschwinglich für Schulen"}, {"text": "Programmierbare Schnittstellen", "correct": true, "because": "Fördert Experimente"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht primär"}, {"text": "Vorinstallierte Spiele", "correct": false, "because": "Kein Lernfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Netzwerkprojekt unwichtig?', 3, '[{"text": "Stabile Verbindung", "correct": false, "because": "Kern der Funktionalität"}, {"text": "Firewall-Konfiguration", "correct": false, "because": "Sichert Daten"}, {"text": "Tastaturlayout", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Board als NAS einrichte?', 4, '[{"text": "Externe Festplatte und Samba installieren", "correct": true, "because": "Ermöglicht Dateifreigabe"}, {"text": "High-End-GPU einbauen", "correct": false, "because": "Nicht nötig"}, {"text": "Spiegelserver einrichten", "correct": false, "because": "Zu komplex"}]');
